def freeze_existing_started_match_timer_policy(apps, schema_editor):
    """Mark fixtures that had already genuinely started before timer support.

    A newly configured tournament timer must apply only when a fixture enters
    live play for the first time.  Existing postponed fixtures can have been
    started previously, so without this marker resuming one after the schema
    upgrade could incorrectly attach a later organiser setting.  We retain
    their intentionally unlimited policy while leaving merely rescheduled,
    never-started fixtures eligible for a future timer snapshot.
    """

    Match = apps.get_model("pool", "PoolMatch")
    Revision = apps.get_model("pool", "PoolMatchResultRevision")
    database = schema_editor.connection.alias
    now = timezone.now()

    Match.objects.using(database).filter(
        timer_snapshot_at__isnull=True,
    ).filter(
        Q(status__in=["LIVE", "FINISHED", "ABANDONED"])
        | Q(status="POSTPONED", racks__isnull=False)
        | Q(
            pk__in=Revision.objects.using(database)
            .filter(action="MATCH_STARTED")
            .values("match_id")
        )
    ).update(timer_snapshot_at=now)


def preserve_existing_timer_policy_markers(apps, schema_editor):
    """Timer snapshots are historical audit evidence and remain on reverse."""


